const bins = $input.item.binary || {};
const key = Object.keys(bins)[0];
if (!key) { throw new Error('Файл не получен'); }
const buf = await this.helpers.getBinaryDataBuffer(0, key);
const parsed = JSON.parse(buf.toString('utf8'));
const chunks = Array.isArray(parsed) ? parsed : (parsed.chunks || []);
return { json: { chunks: chunks, total: chunks.length } };

const chunks = $('Прочитать файл').first().json.chunks || [];
const B = 50;
const out = [];
for (let i = 0; i < chunks.length; i += B) {
  out.push({ json: { batch: chunks.slice(i, i + B), batchIndex: i / B } });
}
return out;

const batch = $('Собрать батчи').item.json.batch || [];
const preds = $json.predictions || [];
const vectors = batch.map((c, i) => ({
  id: c.id,
  values: (preds[i] && preds[i].embeddings && preds[i].embeddings.values) || [],
  metadata: { glava: c.glava || '', punkt: (c.punkt != null ? String(c.punkt) : ''), text: c.text || '', source: 'prikaz-90', version: c.version || '' }
})).filter(v => v.values.length > 0);
return { json: { vectors } };
